BEGIN;

DO $$
DECLARE
  org_id constant uuid := '00000000-0000-4000-8000-000000000001';
  director_user constant uuid := '10000000-0000-4000-8000-000000000001';
BEGIN
  IF NOT EXISTS(SELECT 1 FROM organizations WHERE id=org_id) THEN RETURN; END IF;

  PERFORM set_config('app.organization_id',org_id::text,true);
  PERFORM set_config('app.user_id',director_user::text,true);

  ON CONFLICT(id) DO UPDATE SET code=EXCLUDED.code,name=EXCLUDED.name,active=true;

  ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,legal_name=EXCLUDED.legal_name,status='active',owner_user_id=EXCLUDED.owner_user_id,assigned_team_id=EXCLUDED.assigned_team_id,region_id=EXCLUDED.region_id;

  ON CONFLICT(id) DO UPDATE SET client_company_id=EXCLUDED.client_company_id,title=EXCLUDED.title,status='accepted',location_text=EXCLUDED.location_text,region_id=EXCLUDED.region_id,expected_start_date=EXCLUDED.expected_start_date,schedule_json=EXCLUDED.schedule_json,housing_rule=EXCLUDED.housing_rule,owner_user_id=EXCLUDED.owner_user_id,assigned_team_id=EXCLUDED.assigned_team_id,workflow_stage_code='agreed';

  SELECT '7a000000-0000-4000-8000-000000000001',org_id,'73000000-0000-4000-8000-000000000001',1,'accepted','{}'::uuid[],2460000,'{"requestId":"73000000-0000-4000-8000-000000000001","title":"РЦ Северный — запуск складского персонала","objectName":"РЦ Северный","clientId":"70000000-0000-4000-8000-000000000001","location":"Московская область, Дмитровский округ","schedule":"6/1 · 12 ч присутствие · 11 ч оплачивается","housing":"Включить","vat":"С НДС","roles":[{"name":"Комплектовщик","count":10},{"name":"Грузчик","count":4},{"name":"Водитель погрузчика","count":2},{"name":"Бригадир","count":2}]}'::jsonb,'10000000-0000-4000-8000-000000000008',director_user,'2026-08-20 09:00+03'::timestamptz,'2026-08-20 10:00+03'::timestamptz,'2026-08-20 11:00+03'::timestamptz,'2026-08-20 12:00+03'::timestamptz,'2026-09-02 09:00+03'::timestamptz
  WHERE NOT EXISTS(SELECT 1 FROM proposals x WHERE x.request_id='73000000-0000-4000-8000-000000000001'::uuid AND x.status='accepted')
  ON CONFLICT(id) DO NOTHING;

  SELECT '7a000000-0000-4000-8000-000000000002',org_id,'73000000-0000-4000-8000-000000000002',1,'accepted','{}'::uuid[],1680000,'{"requestId":"73000000-0000-4000-8000-000000000002","title":"Пищекомбинат Серпухов — производственная смена","objectName":"Пищекомбинат Серпухов","clientId":"70000000-0000-4000-8000-000000000002","location":"Московская область, Серпухов","schedule":"6/1 · 11 ч","housing":"Включить","vat":"С НДС","roles":[{"name":"Упаковщик","count":4},{"name":"Фасовщик","count":3},{"name":"Мойщик оборудования","count":2},{"name":"Бригадир","count":3}]}'::jsonb,'10000000-0000-4000-8000-000000000009',director_user,'2026-09-02 09:00+03'::timestamptz,'2026-09-02 10:00+03'::timestamptz,'2026-09-02 11:00+03'::timestamptz,'2026-09-02 12:00+03'::timestamptz,'2026-09-15 09:00+03'::timestamptz
  WHERE NOT EXISTS(SELECT 1 FROM proposals x WHERE x.request_id='73000000-0000-4000-8000-000000000002'::uuid AND x.status='accepted')
  ON CONFLICT(id) DO NOTHING;

  SELECT '7a000000-0000-4000-8000-000000000003',org_id,'73000000-0000-4000-8000-000000000003',1,'accepted','{}'::uuid[],3270000,'{"requestId":"73000000-0000-4000-8000-000000000003","title":"ЭлектроМаш Владимир — производственный персонал","objectName":"ЭлектроМаш Владимир","clientId":"70000000-0000-4000-8000-000000000003","location":"Владимир, промышленная зона Восточная","schedule":"6/1 · 11 ч","housing":"Включить","vat":"С НДС","roles":[{"name":"Электромонтажник","count":4},{"name":"Сборщик","count":5},{"name":"Сварщик","count":2},{"name":"Разнорабочий","count":4},{"name":"Бригадир","count":3}]}'::jsonb,'10000000-0000-4000-8000-000000000008',director_user,'2026-03-11 09:00+03'::timestamptz,'2026-03-11 10:00+03'::timestamptz,'2026-03-11 11:00+03'::timestamptz,'2026-03-11 12:00+03'::timestamptz,'2026-03-24 09:00+03'::timestamptz
  WHERE NOT EXISTS(SELECT 1 FROM proposals x WHERE x.request_id='73000000-0000-4000-8000-000000000003'::uuid AND x.status='accepted')
  ON CONFLICT(id) DO NOTHING;

  SELECT '7a000000-0000-4000-8000-000000000004',org_id,'73000000-0000-4000-8000-000000000004',1,'accepted','{}'::uuid[],2140000,'{"requestId":"73000000-0000-4000-8000-000000000004","title":"Склад Маркет Подольск — усиление смен","objectName":"Склад Маркет Подольск","clientId":"70000000-0000-4000-8000-000000000004","location":"Московская область, Подольск","schedule":"5/2 и 6/1 · 11 ч","housing":"Не требуется","vat":"С НДС","roles":[{"name":"Комплектовщик","count":5},{"name":"Приёмщик товара","count":2},{"name":"Упаковщик","count":4},{"name":"Бригадир","count":3}]}'::jsonb,'10000000-0000-4000-8000-000000000009',director_user,'2026-06-24 09:00+03'::timestamptz,'2026-06-24 10:00+03'::timestamptz,'2026-06-24 11:00+03'::timestamptz,'2026-06-24 12:00+03'::timestamptz,'2026-07-07 09:00+03'::timestamptz
  WHERE NOT EXISTS(SELECT 1 FROM proposals x WHERE x.request_id='73000000-0000-4000-8000-000000000004'::uuid AND x.status='accepted')
  ON CONFLICT(id) DO NOTHING;

  SELECT '7a000000-0000-4000-8000-000000000005',org_id,'73000000-0000-4000-8000-000000000005',1,'accepted','{}'::uuid[],1310000,'{"requestId":"73000000-0000-4000-8000-000000000005","title":"Технопарк Калуга — клининг и эксплуатация","objectName":"Технопарк Калуга","clientId":"70000000-0000-4000-8000-000000000005","location":"Калуга, индустриальный парк Ворсино","schedule":"6/1 · 11 ч","housing":"По потребности","vat":"С НДС","roles":[{"name":"Уборщик производственных помещений","count":4},{"name":"Оператор поломоечной машины","count":2},{"name":"Разнорабочий","count":2},{"name":"Бригадир","count":2}]}'::jsonb,'10000000-0000-4000-8000-000000000008',director_user,'2026-07-24 09:00+03'::timestamptz,'2026-07-24 10:00+03'::timestamptz,'2026-07-24 11:00+03'::timestamptz,'2026-07-24 12:00+03'::timestamptz,'2026-08-06 09:00+03'::timestamptz
  WHERE NOT EXISTS(SELECT 1 FROM proposals x WHERE x.request_id='73000000-0000-4000-8000-000000000005'::uuid AND x.status='accepted')
  ON CONFLICT(id) DO NOTHING;

  ON CONFLICT(id) DO UPDATE SET client_company_id=EXCLUDED.client_company_id,source_request_id=EXCLUDED.source_request_id,source_proposal_id=EXCLUDED.source_proposal_id,name=EXCLUDED.name,code=EXCLUDED.code,status='active',region_id=EXCLUDED.region_id,address_text=EXCLUDED.address_text,target_start_date=EXCLUDED.target_start_date,owner_user_id=EXCLUDED.owner_user_id;

  DELETE FROM object_assignments WHERE organization_id=org_id AND object_id IN ('80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000002','80000000-0000-4000-8000-000000000003','80000000-0000-4000-8000-000000000004','80000000-0000-4000-8000-000000000005');

  ON CONFLICT(id) DO UPDATE SET object_id=EXCLUDED.object_id,source_request_role_id=NULL,specialty_id=EXCLUDED.specialty_id,count_required=EXCLUDED.count_required,count_filled=EXCLUDED.count_filled,deadline=EXCLUDED.deadline,status=EXCLUDED.status,owner_user_id=EXCLUDED.owner_user_id,region_id=EXCLUDED.region_id,source_kind='object',title=EXCLUDED.title,priority=EXCLUDED.priority,conditions_snapshot=EXCLUDED.conditions_snapshot,manager_user_id=EXCLUDED.manager_user_id;

  DELETE FROM need_assignments WHERE organization_id=org_id AND need_id IN ('83000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000003','83000000-0000-4000-8000-000000000004','83000000-0000-4000-8000-000000000005','83000000-0000-4000-8000-000000000006','83000000-0000-4000-8000-000000000007','83000000-0000-4000-8000-000000000008','83000000-0000-4000-8000-000000000009','83000000-0000-4000-8000-000000000010','83000000-0000-4000-8000-000000000011','83000000-0000-4000-8000-000000000012','83000000-0000-4000-8000-000000000013','83000000-0000-4000-8000-000000000014','83000000-0000-4000-8000-000000000015','83000000-0000-4000-8000-000000000016','83000000-0000-4000-8000-000000000017','83000000-0000-4000-8000-000000000018','83000000-0000-4000-8000-000000000019','83000000-0000-4000-8000-000000000020','83000000-0000-4000-8000-000000000021');

  ON CONFLICT(id) DO UPDATE SET full_name=EXCLUDED.full_name,phone=EXCLUDED.phone,source=EXCLUDED.source,original_recruiter_user_id=EXCLUDED.original_recruiter_user_id,current_recruiter_user_id=EXCLUDED.current_recruiter_user_id,created_by_user_id=EXCLUDED.created_by_user_id,status='active',email=EXCLUDED.email,preferred_channel=EXCLUDED.preferred_channel,telegram=EXCLUDED.telegram,whatsapp=EXCLUDED.whatsapp,city=EXCLUDED.city,source_channel=EXCLUDED.source_channel,source_campaign=EXCLUDED.source_campaign,source_reference=EXCLUDED.source_reference,updated_at=EXCLUDED.updated_at;

  ON CONFLICT(id) DO UPDATE SET candidate_id=EXCLUDED.candidate_id,need_id=EXCLUDED.need_id,object_id=EXCLUDED.object_id,stage=EXCLUDED.stage,next_action_at=EXCLUDED.next_action_at,owner_user_id=EXCLUDED.owner_user_id,planned_start_date=EXCLUDED.planned_start_date,actual_start_at=EXCLUDED.actual_start_at,rejection_reason=EXCLUDED.rejection_reason,manager_user_id=EXCLUDED.manager_user_id,conditions_snapshot=EXCLUDED.conditions_snapshot,rejection_reason_code=EXCLUDED.rejection_reason_code,updated_at=now();

  ON CONFLICT(id) DO UPDATE SET origin_candidate_id=NULL,full_name=EXCLUDED.full_name,status='active',source=EXCLUDED.source,original_recruiter_user_id=EXCLUDED.original_recruiter_user_id,created_by_user_id=EXCLUDED.created_by_user_id,updated_at=now();

  ON CONFLICT(id) DO UPDATE SET relation_type=EXCLUDED.relation_type,effective_from=EXCLUDED.effective_from,effective_to=NULL,created_by_user_id=EXCLUDED.created_by_user_id;

  ON CONFLICT(id) DO UPDATE SET worker_id=EXCLUDED.worker_id,specialty_id=EXCLUDED.specialty_id,object_id=EXCLUDED.object_id,amount=EXCLUDED.amount,unit='hour',effective_from=EXCLUDED.effective_from,effective_to=NULL;

  ON CONFLICT(id) DO UPDATE SET worker_id=EXCLUDED.worker_id,object_id=EXCLUDED.object_id,specialty_id=EXCLUDED.specialty_id,effective_from=EXCLUDED.effective_from,effective_to=NULL,manager_user_id=EXCLUDED.manager_user_id,created_by_user_id=EXCLUDED.created_by_user_id;

  IF (SELECT count(*) FROM worker_profiles w WHERE w.organization_id=org_id AND w.status='active' AND w.id::text LIKE '88000000-0000-4000-8000-%') <> 44 THEN
    RAISE EXCEPTION 'beta workforce must contain exactly 44 active workers';
  END IF;
  IF (SELECT count(*) FROM candidates c WHERE c.organization_id=org_id AND c.id::text LIKE '85000000-0000-4000-8000-%') <> 50 THEN
    RAISE EXCEPTION 'beta recruiting must contain exactly 50 candidates';
  END IF;
  IF EXISTS(
    SELECT 1 FROM candidates c
    WHERE c.organization_id=org_id AND c.id::text LIKE '85000000-0000-4000-8000-%'
      AND c.current_recruiter_user_id NOT IN (
        '10000000-0000-4000-8000-000000000012'::uuid,
        '10000000-0000-4000-8000-000000000013'::uuid,
        '10000000-0000-4000-8000-000000000014'::uuid
      )
  ) THEN RAISE EXCEPTION 'every beta candidate must have a recruiter'; END IF;
  IF EXISTS(
    SELECT o.id FROM objects o
    WHERE o.organization_id=org_id AND o.id::text LIKE '80000000-0000-4000-8000-%'
      AND NOT EXISTS(
        SELECT 1 FROM worker_object_assignments a JOIN worker_profiles w ON w.id=a.worker_id AND w.status='active'
        WHERE a.object_id=o.id AND a.effective_from<=current_date AND (a.effective_to IS NULL OR a.effective_to>=current_date)
      )
  ) THEN RAISE EXCEPTION 'every beta object must have active workers'; END IF;

END $$;

COMMIT;
